function SubjectBreakdown({rows}){return <div className="breakdown-list">{rows.map(({subject,total,present,absent,pct})=><div className="breakdown-row" key={subject.id}><div className="breakdown-top"><div><b>{subject.subjectName}</b><small>{subject.subjectCode} · {present} present · {absent} absent</small></div><strong className={pct<75?'low-pct':''}>{pct}%</strong><em className={`attendance-level ${attendanceTone(pct)}`}>{attendanceLabel(pct)}</em></div><div className="progress-track"><span style={{width:`${pct}%`}}/></div><small className="class-total">{total} total classes</small></div>)}{!rows.length&&<div className="empty">No subjects available.</div>}</div>}
function attendanceLabel(pct){return pct<75?'Low attendance':pct<85?'Average attendance':'Good attendance'}
